#!/usr/bin/env python3
# Generated by test-lab — blind adversarial evaluation
"""First live test: Embry talks while she works.

Simplified integration test that proves:
1. espeak-ng → PipeWire → Jabra SPEAK 510 audio path works
2. Scenario steps execute via AT-SPI
3. Embry narrates each step aloud
4. Between steps, she pauses (humming comes later)

No human mic input needed. Just Embry solo.

Usage:
    cd .pi/skills/converse
    python3 test_solo_work_talk.py

    # Or with a real scenario:
    python3 test_solo_work_talk.py --scenario ../surf-qml/scenarios/design_review.yaml

    # Audio-only test (no AT-SPI, just speak):
    python3 test_solo_work_talk.py --audio-only
"""

from __future__ import annotations
import os

from typing import Optional
import asyncio
import subprocess
import sys
import time
from pathlib import Path

# ---------------------------------------------------------------------------
# Phase 1: Verify espeak-ng → PipeWire audio path
# ---------------------------------------------------------------------------

def test_espeak():
    """Verify espeak-ng can produce audio and PipeWire can play it."""
    print("=== Phase 1: Audio Path Test ===")
    print("Testing espeak-ng → PipeWire → Jabra...")

    # Check espeak-ng exists
    result = subprocess.run(["which", "espeak-ng"], capture_output=True,
        env={k: v for k, v in os.environ.items() if k != 'VIRTUAL_ENV'},
    )
    if result.returncode != 0:
        print("FAIL: espeak-ng not installed. Run: sudo apt install espeak-ng")
        return False

    # Check PipeWire
    result = subprocess.run(["pw-cli", "info", "0"], capture_output=True,
    env={k: v for k, v in os.environ.items() if k != "VIRTUAL_ENV"},
    )
    if result.returncode != 0:
        print("FAIL: PipeWire not running",
            env={k: v for k, v in os.environ.items() if k != 'VIRTUAL_ENV'},
        )
        return False

    # Speak a test sentence
    print("Speaking: 'Hello. I am Embry. Let me check the interface.'")
    result = subprocess.run(
        ["espeak-ng", "-v", "en-us", "-s", "160", "-p", "75",
         "Hello. I am Embry. Let me check the interface."],
        timeout=10,
        env={k: v for k, v in os.environ.items() if k != "VIRTUAL_ENV"},
    )
    if result.returncode != 0:
        print(f"FAIL: espeak-ng returned {result.returncode}")
        return False

    print("OK: Audio path works\n")
    return True


# ---------------------------------------------------------------------------
# Phase 2: Test Speaker class (our TTS wrapper)
# ---------------------------------------------------------------------------

async def test_speaker():
    """Test the Speaker class from the converse skill."""
    print("=== Phase 2: Speaker Class Test ===")

    # Add converse skill to path
    skill_dir = Path(__file__).parent
    sys.path.insert(0, str(skill_dir),
    env={k: v for k, v in os.environ.items() if k != 'VIRTUAL_ENV'},
    )

    from speaker import Speaker
    from emotion import EmotionState

    speaker = Speaker(persona="embry", mode="recorded")  # recorded mode uses espeak fallback

    sentences = [
        ("Okay, starting the design review.", "confident", EmotionState.FOCUSED),
        ("Hmm, that doesn't look right.", "uncertain", EmotionState.CONFUSED),
        ("There we go. Much better.", "confident", EmotionState.PLEASED),
    ]

    for text, register, emotion in sentences:
        print(f"  Speaking [{register}]: {text}")
        chunks = await speaker.speak(text, register=register, emotion=emotion)
        if chunks:
            total = sum(c.audio.shape[0] for c in chunks)
            print(f"    Generated {total} samples")
            # Play through pw-play
            import numpy as np
            audio = np.concatenate([c.audio for c in chunks])
            proc = await asyncio.create_subprocess_exec(
                "pw-play", "--format", "s16", "--rate", str(chunks[0].sample_rate),
                "--channels", "1", "-",
                stdin=asyncio.subprocess.PIPE,
            )
            await proc.communicate(input=audio.tobytes())
        else:
            print("    WARN: No audio generated")
        await asyncio.sleep(0.5)

    print("OK: Speaker works\n")
    return True


# ---------------------------------------------------------------------------
# Phase 3: Full scenario with narration
# ---------------------------------------------------------------------------

async def test_scenario_narration(scenario_path: str):
    """Run a scenario and have Embry narrate through Speaker."""
    print("=== Phase 3: Scenario + Narration ===")

    skill_dir = Path(__file__).parent
    sys.path.insert(0, str(skill_dir))

    from scenario_bridge import AsyncScenarioExecutor
    from speaker import Speaker
    from emotion import EmotionState, EmotionStateMachine
    import numpy as np

    speaker = Speaker(persona="embry", mode="recorded")
    emotion = EmotionStateMachine(persona="embry")
    executor = AsyncScenarioExecutor(scenario_path)

    # Opening line
    print("Embry: Starting the scenario.")
    await _speak_and_play(speaker, "Alright, let me run through this scenario.", "confident", EmotionState.FOCUSED)

    # Start executor
    exec_task = asyncio.create_task(executor.run())

    step_count = 0
    while True:
        try:
            result = await asyncio.wait_for(executor.queue.get(), timeout=5.0)
        except asyncio.TimeoutError:
            if exec_task.done():
                break
            continue

        step_count += 1
        status_icon = "OK" if result.status == "ok" else "FAIL"
        print(f"  Step {result.step_num}/{result.total_steps}: "
              f"{result.action} → {status_icon}: {result.detail}")

        # Update emotion
        if result.emotion_hint:
            emotion.update(result.emotion_hint, 0.7, trigger=f"scenario_{result.action}")

        # Narrate
        if result.narration:
            register = "confident"
            if emotion.state in (EmotionState.FRUSTRATED,):
                register = "tense"
            elif emotion.state in (EmotionState.CONFUSED,):
                register = "uncertain"

            print(f"  Embry [{register}]: {result.narration}")
            await _speak_and_play(speaker, result.narration, register, emotion.state)

        if result.is_final:
            break

    # Wait for executor to finish
    if not exec_task.done():
        await exec_task

    # Closing line
    summary = f"Done. {step_count} steps completed."
    print(f"Embry: {summary}")
    await _speak_and_play(speaker, summary, "confident", EmotionState.PLEASED)

    print("OK: Scenario narration complete\n")
    return True


async def _speak_and_play(speaker, text: str, register: str, emotion):
    """Synthesize and play through PipeWire."""
    import numpy as np
    chunks = await speaker.speak(text, register=register, emotion=emotion)
    if chunks:
        audio = np.concatenate([c.audio for c in chunks])
        proc = await asyncio.create_subprocess_exec(
            "pw-play", "--format", "s16", "--rate", str(chunks[0].sample_rate),
            "--channels", "1", "-",
            stdin=asyncio.subprocess.PIPE,
        )
        await proc.communicate(input=audio.tobytes())
    await asyncio.sleep(0.3)


# ---------------------------------------------------------------------------
# Phase 4: Minimal scenario (no AT-SPI needed)
# ---------------------------------------------------------------------------

async def test_audio_only():
    """Just test Embry talking — no AT-SPI, no scenario.

    Simulates a work session where she narrates observations.
    """
    print("=== Audio-Only Work Talk Test ===")

    skill_dir = Path(__file__).parent
    sys.path.insert(0, str(skill_dir))

    from speaker import Speaker
    from emotion import EmotionState

    speaker = Speaker(persona="embry", mode="recorded")

    lines = [
        ("Okay, let me open up the design review.", "confident", EmotionState.FOCUSED),
        ("Looking at the landing page...", "confident", EmotionState.CURIOUS),
        ("The typography looks consistent. Good spacing.", "confident", EmotionState.PLEASED),
        ("Wait... the search bar is misaligned. That's off by a few pixels.", "uncertain", EmotionState.CONFUSED),
        ("Let me check the contrast ratios.", "confident", EmotionState.FOCUSED),
        ("Hmm. The secondary text might not meet accessibility standards.", "tense", EmotionState.FRUSTRATED),
        ("I'll flag that for review.", "confident", EmotionState.FOCUSED),
        ("Moving on to the navigation...", "confident", EmotionState.NEUTRAL),
        ("Everything else looks clean. Nice work.", "confident", EmotionState.PLEASED),
        ("Alright, that's the review done.", "confident", EmotionState.PLEASED),
    ]

    for text, register, emotion in lines:
        print(f"  Embry [{register}]: {text}")
        await _speak_and_play(speaker, text, register, emotion)
        # Pause between lines like natural speech
        await asyncio.sleep(0.8)

    print("\nOK: Audio-only test complete")
    return True


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def _cli(
    scenario: Optional[str] = typer.Option(None, help="Path to scenario YAML"),
    audio_only: bool = typer.Option(False, help="Skip AT-SPI, just test speech"),
    skip_phase1: bool = typer.Option(False, help="Skip basic espeak test"),
) -> None:
    """Test Embry solo work-talk."""
    async def _run():
        if not skip_phase1:
            if not test_espeak():
                raise SystemExit(1)

        if audio_only:
            await test_audio_only()
        elif scenario:
            await test_speaker()
            await test_scenario_narration(scenario)
        else:
            await test_speaker()
            # Default: audio-only work talk
            await test_audio_only()

        print("\n=== All tests passed ===")

    asyncio.run(_run())


if __name__ == "__main__":
    import typer
    typer.run(_cli)
